mutable struct Env
    frame::Dict{Symbol,Any}
    parent::Union{Env,Nothing}
    Env(p=nothing)=new(Dict{Symbol,Any}(),p)
mutable struct Procedure
    name::Union{Symbol,Nothing}
    minimum::Int
    rest::Union{Bool,Symbol}
    params::Vector{Symbol}
    body::Vector{Any}
    env::Union{Env,Nothing}
    builtin::Union{Function,Nothing}
function findenv(e,n)
    while !isnothing(e)
        haskey(e.frame,n) && return e
        e=e.parent
function lookup(e,n)
    v=findenv(e,n).frame[n]
    v===UNINIT && fail("uninitialized variable: $n")
    v
compound(p,b,e,n=nothing)=Procedure(n,length(p[1]),p[2],p[1],Any[b...],e,nothing)
function eval_body(a,e)
    v=VOID
    for x in a;
        v=evaluate(x,e);
    v
function call_proc(f,a)
    e=Env(f.env)
    eval_body(f.body,e)
function evaluate(x,e)
    x isa Symbol && return lookup(e,x)
    elseif h=="lambda";
        return compound(p,a[3:end],e)
    elseif h=="set!";
        v=evaluate(a[3],e);
        findenv(e,a[2]).frame[a[2]]=v;
    elseif h in ("let","let*","letrec")
        named=h=="let"&&n>1&&a[2] isa Symbol;
        at=named ? 3 : 2
        bs=n>=at+1 ? bindings(a[at],h!="let*") : nothing;
        s=Env(e)
        if h=="let*"
            !isempty(bs) && (s=e)
            for (name,expr) in bs;
                v=evaluate(expr,s);
                s=Env(s);
                s.frame[name]=v;
        elseif h=="letrec"
            for (name,_) in bs;
                s.frame[name]=UNINIT;
            for (name,expr) in bs;
                s.frame[name]=evaluate(expr,s);
        else
            vs=Any[evaluate(b[2],e) for b in bs]
            for (b,v) in zip(bs,vs);
                s.frame[b[1]]=v;
        return eval_body(a[at+1:end],s)
    f=evaluate(a[1],e);
    args=Any[evaluate(z,e) for z in a[2:end]]
    call_proc(f,args)
